def fix2(g):
    h,w=len(g),len(g[0]); g=[r[:] for r in g]
    for _ in range(50):
        ch=False
        for i in range(h):
            for j in range(w):
                if g[i][j]==2:
                    cands=[g[h-1-i][j],g[i][w-1-j],g[h-1-i][w-1-j],g[j][i]]
                    nz=[c for c in cands if c!=2]
                    if nz: g[i][j]=nz[0]; ch=True
        if not ch: break
    return g
